(function(){'use strict';
const KEY='nawaf-hq-v5';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const active=new Set(['WORKING','RESEARCHING','REVIEWING']);
const icons={
 dashboard:'<svg viewBox="0 0 24 24"><path d="M4 13h6V4H4v9Zm10 7h6V11h-6v9ZM4 20h6v-3H4v3Zm10-13h6V4h-6v3Z"/></svg>',
 workforce:'<svg viewBox="0 0 24 24"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm9-4v6m3-3h-6"/></svg>',
 projects:'<svg viewBox="0 0 24 24"><path d="M3 7h6l2 2h10v10H3V7Zm0 0V5h7l2 2"/></svg>',
 tasks:'<svg viewBox="0 0 24 24"><path d="m4 6 2 2 4-4M4 13l2 2 4-4M13 7h7m-7 7h7m-7 6h7"/></svg>',
 reports:'<svg viewBox="0 0 24 24"><path d="M5 3h14v18H5V3Zm4 5h6m-6 4h6m-6 4h4"/></svg>'
};
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function ago(v){const t=Date.parse(v||'');if(!Number.isFinite(t))return '';const m=Math.max(1,Math.floor((Date.now()-t)/60000));return m<60?`منذ ${m} د`:m<1440?`منذ ${Math.floor(m/60)} س`:`منذ ${Math.floor(m/1440)} ي`}
function status(v){return ({READY:'جاهزة',IDLE:'متاحة',WORKING:'تعمل الآن',RESEARCHING:'تبحث الآن',REVIEWING:'تراجع',WAITING_FOR_NAWAF:'بانتظارك',BLOCKED:'متعطلة',BLOCKED_BY_TOOL:'تحتاج أداة',COMPLETED:'مكتملة',PAUSED:'متوقفة'})[v]||v||'جاهزة'}
function stats(s){const tasks=s.tasks||[],done=tasks.filter(t=>t.status==='COMPLETED').length;return {tasks,active:tasks.filter(t=>active.has(t.status)),waiting:tasks.filter(t=>t.status==='WAITING_FOR_NAWAF'),blocked:tasks.filter(t=>t.blockedReason&&t.status!=='COMPLETED'),done,completion:tasks.length?Math.round(done/tasks.length*100):0}}
function projectHealth(p,s){const ts=(s.tasks||[]).filter(t=>t.projectId===p.id),bad=ts.filter(t=>t.blockedReason||t.status==='WAITING_FOR_NAWAF').length,done=ts.filter(t=>t.status==='COMPLETED').length;return {total:ts.length,bad,score:p.status==='PAUSED'?55:Math.max(0,100-Math.min(60,bad*20)-(ts.length&&!done?10:0))}}
function home(s,x){const main=$('.v8-main');if(!main||!document.body.classList.contains('v20-dashboard'))return;let root=$('.v20-home');if(!root){root=document.createElement('section');root.className='v20-home v14-dashboard';main.querySelector('.v8-header')?.insertAdjacentElement('afterend',root)}const sig=JSON.stringify([x.active.length,x.waiting.length,x.blocked.length,x.done,x.tasks.length,(s.projects||[]).map(p=>[p.id,p.status]),(s.employees||[]).map(e=>[e.id,e.status,e.task]),(s.activity||[]).slice(0,4).map(a=>a.id||a.at)]);if(root.dataset.sig===sig)return;root.dataset.sig=sig;const priority=[...x.waiting,...x.blocked.filter(t=>t.status!=='WAITING_FOR_NAWAF'),...x.active].filter((t,i,a)=>a.findIndex(q=>q.id===t.id)===i).slice(0,4);root.innerHTML=`<div class="v14-hero"></div><div class="v14-kpis"><button data-v20-go="tasks"><b>${x.active.length}</b><span>يعمل الآن</span><small>${(s.employees||[]).filter(e=>active.has(e.status)).length} موظفين نشطين</small></button><button data-v20-decisions><b>${x.waiting.length}</b><span>يحتاج قرارك</span><small>${x.waiting.length?'راجعها الآن':'لا شيء معلق'}</small></button><button data-v20-go="projects"><b>${(s.projects||[]).filter(p=>p.status==='ACTIVE').length}</b><span>مشاريع نشطة</span><small>${(s.projects||[]).length} مشاريع إجمالًا</small></button><button data-v20-sync><b>${window.HQCloud?.status?.().dirty?'!':'✓'}</b><span>المزامنة</span><small>${window.HQCloud?.status?.().dirty?'تغييرات بانتظار الحفظ':'الحالة مستقرة'}</small></button></div><div class="v20-command-grid"><article class="v20-section v20-focus"><header><div><span>FOCUS</span><h3>الأولوية التنفيذية</h3></div><button data-v20-go="tasks">كل المهام</button></header>${priority.length?priority.map((t,i)=>`<button class="v20-focus-row" data-v20-task="${esc(t.id)}"><em>${i+1}</em><span><b>${esc(t.title)}</b><small>${esc(t.blockedReason||status(t.status))}</small></span><i>${esc(t.priority||t.status||'READY')}</i></button>`).join(''):'<div class="v20-section-empty"><b>الوضع هادئ</b><span>لا توجد مهام نشطة أو قرارات معلقة.</span></div>'}</article><article class="v20-section v20-projects"><header><div><span>PROJECTS</span><h3>محفظة المشاريع</h3></div><button data-v20-go="projects">إدارة المشاريع</button></header><div class="v20-project-grid">${(s.projects||[]).map(p=>{const h=projectHealth(p,s);return `<button data-v20-project="${esc(p.id)}"><div><b>${esc(p.name)}</b><small>${esc(p.status||'ACTIVE')} · ${h.total} مهام</small></div><strong>${h.score}%</strong><span><i style="width:${h.score}%"></i></span>${h.bad?`<em>${h.bad} تحتاج انتباه</em>`:'<em class="ok">مستقر</em>'}</button>`}).join('')||'<div class="v20-section-empty">لا توجد مشاريع.</div>'}</div></article><article class="v20-section v20-team"><header><div><span>AI WORKFORCE</span><h3>الفريق الآن</h3></div><button data-v20-go="workforce">كل الموظفين</button></header><div>${(s.employees||[]).slice(0,6).map(e=>`<button data-v20-employee="${esc(e.id)}"><span>${esc((e.name||'AI').slice(0,1))}</span><div><b>${esc(e.name)}</b><small>${esc(e.role||e.department||'موظف AI')}</small></div><i class="${active.has(e.status)?'busy':''}">${esc(status(e.status))}</i></button>`).join('')}</div></article><article class="v20-section v20-live"><header><div><span>TRUTHFUL ACTIVITY</span><h3>آخر النشاط المسجل</h3></div></header>${(s.activity||[]).slice(0,5).map(a=>`<div><i></i><p><b>${esc(a.text||'نشاط مسجل')}</b><small>${ago(a.at)}</small></p></div>`).join('')||'<div class="v20-section-empty"><b>لا يوجد نشاط بعد</b><span>سيظهر هنا كل تنفيذ حقيقي مسجل.</span></div>'}</article></div><div class="v20-actions"><button data-v14-action="quick">✦ أمر سريع</button><button data-action="new-task">＋ مهمة جديدة</button><button data-finance-open>◫ المحلل المالي</button><button data-v14-action="decisions">⚑ القرارات</button><a href="apps.html">▣ تطبيقاتي</a></div>`;hero(s,x);root.querySelectorAll('[data-v20-go]').forEach(b=>b.onclick=()=>document.querySelector(`[data-view="${b.dataset.v20Go}"]`)?.click());root.querySelectorAll('[data-v20-employee]').forEach(b=>b.onclick=()=>document.querySelector(`[data-employee="${CSS.escape(b.dataset.v20Employee)}"]`)?.click());root.querySelectorAll('[data-v20-project]').forEach(b=>b.onclick=()=>document.querySelector(`[data-project="${CSS.escape(b.dataset.v20Project)}"]`)?.click());root.querySelectorAll('[data-v20-task]').forEach(b=>b.onclick=()=>document.querySelector(`[data-task="${CSS.escape(b.dataset.v20Task)}"]`)?.click());root.querySelectorAll('[data-v20-decisions],[data-v14-action="decisions"]').forEach(b=>b.onclick=()=>window.NawafHQV13?.openCenter?.()||$('#exec-secretary-toggle')?.click());root.querySelector('[data-v14-action="quick"]')?.addEventListener('click',()=>document.querySelector('[data-v9-quick]')?.click());root.querySelector('[data-finance-open]')?.addEventListener('click',()=>window.NawafFinance?.open?.());root.querySelector('[data-v20-sync]')?.addEventListener('click',async()=>{await window.HQCloud?.pull?.();schedule()})}
function nav(){const brand=$('.v8-brand');if(brand&&!brand.dataset.v20){brand.dataset.v20='1';brand.innerHTML='<span class="v20-brand-mark">N</span><span><b>NAWAF HQ</b><small>AI COMPANY OS</small></span>'}document.querySelectorAll('.v8-side [data-view]').forEach(b=>{const id=b.dataset.view;if(!b.querySelector('.v20-nav-icon'))b.insertAdjacentHTML('afterbegin',`<i class="v20-nav-icon">${icons[id]||''}</i>`)})}
function hero(s,x){const h=$('.v14-hero');if(!h)return;const sig=[x.active.length,x.waiting.length,x.completion,(s.projects||[]).length].join(':');if(h.dataset.v20===sig)return;h.dataset.v20=sig;h.innerHTML=`<div class="v20-hero-copy"><span class="v20-eyebrow"><i></i> مركز قيادة الشركة</span><h2>حوّل قرارك إلى <em>تنفيذ حقيقي.</em></h2><p>المشاريع والفريق والقرارات في واجهة واحدة واضحة — مبنية على بيانات الشركة المسجلة فقط.</p><button class="v20-command" type="button" data-v20-command><span class="v20-command-icon">✦</span><span><b>وش تبغى الشركة تسوي؟</b><small>وجّه الفريق، ابدأ مهمة، أو اطلب تقريرًا</small></span><strong>ابدأ التنفيذ</strong></button><div class="v20-hero-facts"><span><b>${x.active.length}</b> تعمل الآن</span><span><b>${x.waiting.length}</b> تحتاج قرارك</span><span><b>${(s.projects||[]).filter(p=>p.status==='ACTIVE').length}</b> مشاريع نشطة</span></div></div><div class="v20-progress"><span>إنجاز المهام</span><strong>${x.completion}%</strong><div><i style="width:${x.completion}%"></i></div><small>${x.done} مكتملة من ${x.tasks.length}</small></div>`;h.querySelector('[data-v20-command]')?.addEventListener('click',()=>document.querySelector('[data-v9-quick]')?.click())}
function systemState(){const cloud=window.HQCloud?.status?.()||{};return [{label:'محرك التنفيذ',ok:!!(window.NawafAgents||window.NawafProjectExecutor)},{label:'المزامنة السحابية',ok:cloud.cloud!==false,warn:!!cloud.dirty},{label:'واجهة القيادة',ok:true}]}
function rail(s,x){const app=$('.v8');if(!app)return;let r=$('.v20-rail');if(!r){r=document.createElement('aside');r.className='v20-rail';app.appendChild(r)}const sara=(s.employees||[]).find(e=>/سارة|sara/i.test((e.name||'')+' '+(e.id||'')))||(s.employees||[])[0];const saraTask=sara&&x.tasks.find(t=>t.employeeId===sara.id&&active.has(t.status));const activity=(s.activity||[]).slice(0,5),health=systemState();const sig=JSON.stringify([sara?.status,saraTask?.id,x.waiting.length,x.blocked.length,activity.map(a=>a.id||a.at),health]);if(r.dataset.sig===sig)return;r.dataset.sig=sig;r.innerHTML=`<div class="v20-owner"><span>ن</span><div><b>نواف</b><small>الرئيس التنفيذي</small></div><i title="متصل"></i></div><section class="v20-sarah"><header><span>مكتب سارة التنفيذي</span><i class="${active.has(sara?.status)?'busy':''}">${esc(status(sara?.status))}</i></header><div class="v20-sarah-person"><span>${esc((sara?.name||'س').slice(0,1))}</span><div><b>${esc(sara?.name||'سارة')}</b><small>${esc(sara?.role||'السكرتير التنفيذي AI')}</small></div></div><p>${saraTask?`تتابع الآن: ${esc(saraTask.title)}`:'لا توجد مهمة نشطة مسجلة حاليًا.'}</p>${sara?`<button type="button" data-v20-sarah="${esc(sara.id)}">فتح المكتب وإعطاء أمر</button>`:''}</section><section class="v20-attention"><header><span>يحتاج انتباهك</span><b>${x.waiting.length+x.blocked.length}</b></header>${x.waiting.length+x.blocked.length?`<p>${x.waiting.length} قرارات بانتظارك و${x.blocked.length} عوائق حقيقية مسجلة.</p><button type="button" data-v20-decisions>مراجعة القرارات</button>`:'<div class="v20-clear"><i>✓</i><span><b>لا شيء عاجل</b><small>لا توجد قرارات أو عوائق مسجلة.</small></span></div>'}</section><section class="v20-system"><header><span>صحة النظام</span><small>حالة مباشرة</small></header>${health.map(h=>`<div><span>${h.label}</span><i class="${h.ok&&!h.warn?'ok':h.warn?'warn':'bad'}">${h.ok&&!h.warn?'متصل':h.warn?'مزامنة معلقة':'تحقق'}</i></div>`).join('')}</section><section class="v20-activity"><header><span>النشاط الحقيقي</span><button type="button" data-v20-activity>السجل</button></header>${activity.length?activity.map(a=>`<div><i></i><p><b>${esc(a.text||'نشاط مسجل')}</b><small>${ago(a.at)}</small></p></div>`).join(''):'<div class="v20-empty">لا يوجد نشاط مسجل بعد.</div>'}</section>`;r.querySelector('[data-v20-sarah]')?.addEventListener('click',e=>document.querySelector(`[data-employee="${CSS.escape(e.currentTarget.dataset.v20Sarah)}"]`)?.click());r.querySelector('[data-v20-decisions]')?.addEventListener('click',()=>window.NawafHQV13?.openCenter?.());r.querySelector('[data-v20-activity]')?.addEventListener('click',()=>window.NawafHQV12?.openActivity?.())}
function mark(){document.querySelectorAll('.v8-project').forEach((p,i)=>p.dataset.visual=['mueen','qaddha','nav'][i%3]);document.body.classList.toggle('v20-dashboard',!!$('[data-view="dashboard"].active'));const kicker=$('.v8-header .v8-kicker');if(kicker&&kicker.textContent!=='NAWAF HQ · EXECUTIVE CONTROL')kicker.textContent='NAWAF HQ · EXECUTIVE CONTROL'}
function enhance(){const s=read(),x=stats(s);nav();mark();home(s,x);const decision=$('.v20-home [data-v14-action="decisions"]');if(decision){decision.setAttribute('data-v20-decisions','');decision.removeAttribute('data-v14-action')}rail(s,x)}
let timer=0;function schedule(){clearTimeout(timer);timer=setTimeout(enhance,70)}
function boot(){document.documentElement.dataset.hqDirection='cinematic-tech';const app=$('#app');if(app)new MutationObserver(schedule).observe(app,{childList:true,subtree:true});window.addEventListener('nawaf:state-updated',schedule);document.addEventListener('click',e=>{if(e.target.closest('[data-view]'))setTimeout(enhance,40)});enhance()}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
})();
